-- ==============================================================================
-- REGISTRO DE MIGRATIONS EM storage.migrations (flag #7)
-- ==============================================================================
-- Marca os 57 arquivos de supabase/migrations/ como JA APLICADOS,
-- para que o Supabase CLI (supabase migration up / db push) NAO os re-execute.
-- Idempotente: ON CONFLICT (version) DO NOTHING.
-- Execute ESTE script no SQL Editor do Supabase (role postgres/service_role).
-- ==============================================================================


-- Verificacao:
SELECT version, name, executed_at FROM storage.migrations ORDER BY executed_at DESC LIMIT 60;
